mapper.insert:
INSERT INTO product_review_summaries (product_id, review_count, rating_sum)
VALUES (#{productId}, 1, #{rating})
ON DUPLICATE KEY UPDATE review_count = review_count + 1, rating_sum = rating_sum + #{rating}

mapper.update:
UPDATE product_review_summaries
SET review_count = review_count - 1, rating_sum = rating_sum - #{rating}
WHERE product_id = #{productId} AND review_count > 0 AND rating_sum >= #{rating}
